import re
from dataclasses import dataclass

_NUMBER = r"0|[1-9][0-9]*"
_VERSION = re.compile(
    rf"({_NUMBER})\.({_NUMBER})\.({_NUMBER})"
    r"(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?"
    r"(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?"
)
_COMPARATOR = re.compile(r"(>=|<=|>|<|=|\^|~)?(.*)", re.DOTALL)


@dataclass(frozen=True)
class Version:
    major: int
    minor: int
    patch: int
    prerelease: tuple[str, ...] = ()
    build: tuple[str, ...] = ()

    def __str__(self) -> str:
        """The version in canonical form, e.g. ``1.2.3-rc.1+build.5``."""
        text = f"{self.major}.{self.minor}.{self.patch}"
        if self.prerelease:
            text += "-" + ".".join(self.prerelease)
        if self.build:
            text += "+" + ".".join(self.build)
        return text


def parse(text: str) -> Version:
    """Parse a version string."""
    match = _VERSION.fullmatch(text)
    if not match:
        raise ValueError(f"invalid version: {text!r}")
    major, minor, patch, prerelease, build = match.groups()
    prerelease = tuple(prerelease.split(".")) if prerelease else ()
    if any(i[0] == "0" and len(i) > 1 and i.isdigit() for i in prerelease):
        raise ValueError(f"invalid version: {text!r}")
    build = tuple(build.split(".")) if build else ()
    return Version(int(major), int(minor), int(patch), prerelease, build)


def _version(value: str | Version) -> Version:
    return value if isinstance(value, Version) else parse(value)


def _sign(a, b) -> int:
    return (a > b) - (a < b)


def compare(a: str | Version, b: str | Version) -> int:
    """Return -1, 0, or 1 as ``a`` has lower, equal, or higher precedence."""
    a, b = _version(a), _version(b)
    result = _sign((a.major, a.minor, a.patch), (b.major, b.minor, b.patch))
    if result or not (a.prerelease and b.prerelease):
        # Without a pre-release, a version ranks above the same one with one.
        return result or _sign(not a.prerelease, not b.prerelease)
    for x, y in zip(a.prerelease, b.prerelease):
        if x == y:
            continue
        # Identifiers come from ``parse``, so ``isdigit`` means ASCII digits.
        if x.isdigit() and y.isdigit():
            return _sign(int(x), int(y))
        if x.isdigit() or y.isdigit():
            return -1 if x.isdigit() else 1
        return _sign(x, y)
    return _sign(len(a.prerelease), len(b.prerelease))


_CHECKS = {
    "=": lambda c: c == 0,
    ">": lambda c: c > 0,
    ">=": lambda c: c >= 0,
    "<": lambda c: c < 0,
    "<=": lambda c: c <= 0,
}


def _comparator(text: str) -> tuple[Version, list[tuple[str, Version]]]:
    """The comparator's version, and the primitive comparisons it stands for."""
    operator, rest = _COMPARATOR.fullmatch(text).groups()
    version = parse(rest)
    if operator == "^":
        if version.major:
            upper = Version(version.major + 1, 0, 0)
        elif version.minor:
            upper = Version(0, version.minor + 1, 0)
        else:
            upper = Version(0, 0, version.patch + 1)
        return version, [(">=", version), ("<", upper)]
    if operator == "~":
        upper = Version(version.major, version.minor + 1, 0)
        return version, [(">=", version), ("<", upper)]
    return version, [(operator or "=", version)]


def satisfies(version: str | Version, range_: str) -> bool:
    """Whether ``version`` is in ``range_``."""
    version = _version(version)
    sets = []
    for part in range_.split("||"):
        if not part.split():
            raise ValueError(f"invalid range: {range_!r}")
        try:
            sets.append([_comparator(c) for c in part.split()])
        except ValueError:
            raise ValueError(f"invalid range: {range_!r}") from None

    core = (version.major, version.minor, version.patch)
    for comparators in sets:
        if version.prerelease and not any(
            v.prerelease and (v.major, v.minor, v.patch) == core
            for v, _ in comparators
        ):
            continue
        if all(
            _CHECKS[operator](compare(version, bound))
            for _, checks in comparators
            for operator, bound in checks
        ):
            return True
    return False

