"""Find when a cron schedule next fires.

An expression has five whitespace-separated fields: minute (0-59), hour
(0-23), day of month (1-31), month (1-12), and day of week (0-7, where both
0 and 7 are Sunday). Each field is a comma-separated list of items, where
an item is:

- ``*``, every value in the field's range,
- a value ``N``,
- a range ``A-B`` (inclusive, with ``A <= B``),
- any of those followed by ``/S`` for every ``S``-th value starting at the
  first one (``*/15`` in the minute field is 0, 15, 30, 45; ``10-30/10`` is
  10, 20, 30; ``5/20`` is 5, 25, 45, i.e. from 5 to the end of the range).

Months may also be given by the names ``JAN``-``DEC`` and days of the week
by ``SUN``-``SAT``, in any case, including in ranges. A value outside its
field's range, a malformed item, or a field count other than five raises
``ValueError``.

As in Vixie cron, when both the day-of-month and day-of-week fields are
restricted (neither is exactly ``*``), a day matches if it matches either
one; otherwise it must match both.

Times are naive datetimes. ``next_run`` returns the earliest matching time
strictly after ``after``, with seconds and microseconds zero. If nothing
matches within the next five years (e.g. ``0 0 30 2 *``), it raises
``ValueError``.
"""

from __future__ import annotations

import re
from datetime import datetime, time, timedelta

_MONTHS = {
    name: number
    for number, name in enumerate(
        "JAN FEB MAR APR MAY JUN JUL AUG SEP OCT NOV DEC".split(), start=1
    )
}
_WEEKDAYS = {name: number for number, name in enumerate("SUN MON TUE WED THU FRI SAT".split())}

# (low, high, names) for minute, hour, day of month, month, and day of week.
_FIELDS = [
    (0, 59, {}),
    (0, 23, {}),
    (1, 31, {}),
    (1, 12, _MONTHS),
    (0, 7, _WEEKDAYS),
]

_ITEM = re.compile(r"(\*|[0-9A-Za-z]+(?:-[0-9A-Za-z]+)?)(?:/([0-9]+))?")


def _value(text: str, low: int, high: int, names: dict[str, int]) -> int:
    if text.upper() in names:
        return names[text.upper()]
    # ``isdigit`` alone would accept non-ASCII digits.
    if not (text.isascii() and text.isdigit()):
        raise ValueError(f"invalid value: {text!r}")
    value = int(text)
    if not low <= value <= high:
        raise ValueError(f"value out of range: {text!r}")
    return value


def _field(text: str, low: int, high: int, names: dict[str, int]) -> set[int]:
    values = set()
    for item in text.split(","):
        match = _ITEM.fullmatch(item)
        if not match:
            raise ValueError(f"invalid item: {item!r}")
        span, step = match.groups()
        if span == "*":
            start, end = low, high
        elif "-" in span:
            start, end = (_value(v, low, high, names) for v in span.split("-"))
            if start > end:
                raise ValueError(f"invalid range: {item!r}")
        else:
            start = _value(span, low, high, names)
            end = high if step else start
        step = int(step) if step else 1
        if step == 0:
            raise ValueError(f"invalid step: {item!r}")
        values.update(range(start, end + 1, step))
    return values


def next_run(expression: str, after: datetime) -> datetime:
    """The first time after ``after`` that ``expression`` fires."""
    fields = expression.split()
    if len(fields) != 5:
        raise ValueError(f"expected 5 fields, got {len(fields)}: {expression!r}")
    minutes, hours, days, months, weekdays = (
        sorted(_field(text, *spec)) for text, spec in zip(fields, _FIELDS)
    )
    weekdays = {w % 7 for w in weekdays}  # 7 is also Sunday
    either_day = fields[2] != "*" and fields[4] != "*"

    def day_matches(date) -> bool:
        if date.month not in months:
            return False
        in_month = date.day in days
        # ``weekday`` counts from Monday = 0; cron counts from Sunday = 0.
        in_week = (date.weekday() + 1) % 7 in weekdays
        return in_month or in_week if either_day else in_month and in_week

    try:
        start = after.replace(second=0, microsecond=0) + timedelta(minutes=1)
    except OverflowError:
        raise ValueError(f"no time after {after}") from None
    if start.year + 5 > MAXYEAR:
        limit = datetime.max.replace(tzinfo=after.tzinfo)
    elif start.month == 2 and start.day == 29:
        limit = start.replace(year=start.year + 5, day=28)
    else:
        limit = start.replace(year=start.year + 5)

    date = start.date()
    while True:
        if day_matches(date):
            for hour in hours:
                for minute in minutes:
                    candidate = datetime.combine(
                        date, time(hour, minute), tzinfo=after.tzinfo
                    )
                    if start <= candidate <= limit:
                        return candidate
        if date >= limit.date():
            raise ValueError(f"no match within five years: {expression!r}")
        date += timedelta(days=1)

