from __future__ import annotations

import re

_ALIGNMENTS = (None, "left", "right", "center")
_DELIMITER = re.compile(r"(:?)-+(:?)")


def _cell(value) -> str:
    return "" if value is None else str(value).replace("|", "\\|")


def _pad(text: str, width: int, alignment: str | None) -> str:
    space = width - len(text)
    if alignment == "right":
        return " " * space + text
    if alignment == "center":
        return " " * (space // 2) + text + " " * (space - space // 2)
    return text + " " * space


def _delimiter(width: int, alignment: str | None) -> str:
    left = ":" if alignment in ("left", "center") else "-"
    right = ":" if alignment in ("right", "center") else "-"
    return left + "-" * (width - 2) + right


def format_table(
    header: list, rows: list[list], align: list[str | None] | None = None
) -> str:
    """Write a Markdown table."""
    if align is None:
        align = [None] * len(header)
    if len(align) != len(header):
        raise ValueError(f"expected {len(header)} alignments, got {len(align)}")
    for alignment in align:
        if alignment not in _ALIGNMENTS:
            raise ValueError(f"invalid alignment: {alignment!r}")

    lines = [[_cell(value) for value in header]]
    for row in rows:
        if len(row) > len(header):
            raise ValueError(f"row has more than {len(header)} cells: {row!r}")
        lines.append([_cell(value) for value in row])
        lines[-1] += [""] * (len(header) - len(row))
    widths = [max(3, *(len(line[i]) for line in lines)) for i in range(len(header))]

    def write(cells: list[str]) -> str:
        return "| " + " | ".join(cells) + " |"

    out = [write([_pad(c, w, a) for c, w, a in zip(lines[0], widths, align)])]
    out.append(write([_delimiter(w, a) for w, a in zip(widths, align)]))
    for line in lines[1:]:
        out.append(write([_pad(c, w, a) for c, w, a in zip(line, widths, align)]))
    return "\n".join(out)


def _split(line: str) -> list[str]:
    """Split a table line into stripped, unescaped cells."""
    line = line.strip()
    if line.startswith("|"):
        line = line[1:]
    if line.endswith("|") and not line.endswith("\\|"):
        line = line[:-1]
    cells, cell, i = [], "", 0
    while i < len(line):
        if line.startswith("\\|", i):
            cell += "|"
            i += 2
            continue
        if line[i] == "|":
            cells.append(cell.strip())
            cell = ""
        else:
            cell += line[i]
        i += 1
    cells.append(cell.strip())
    return cells


def parse_table(
    text: str,
) -> tuple[list[str], list[list[str]], list[str | None]]:
    """Read a Markdown table into its header, rows, and alignments."""
    lines = text.strip("\r\n").splitlines()
    if len(lines) < 2:
        raise ValueError("a table needs a header line and a delimiter line")
    header = _split(lines[0])
    delimiters = _split(lines[1])
    if len(delimiters) != len(header):
        raise ValueError(
            f"delimiter line has {len(delimiters)} cells, header has {len(header)}"
        )
    align = []
    for cell in delimiters:
        match = _DELIMITER.fullmatch(cell)
        if not match:
            raise ValueError(f"invalid delimiter cell: {cell!r}")
        left, right = match.groups()
        align.append(
            "center" if left and right else "left" if left else "right" if right else None
        )
    rows = []
    for lineno, line in enumerate(lines[2:], start=3):
        row = _split(line)
        if len(row) != len(header):
            raise ValueError(
                f"line {lineno} has {len(row)} cells, header has {len(header)}"
            )
        rows.append(row)
    return header, rows, align

